class BIT:
    def __init__(self, size):
        self.size = size
        self.tree = [0] * (self.size + 2)  # +2 to avoid issues with 1-based indexing

    def update(self, idx, delta=1):
        while idx <= self.size:
            self.tree[idx] += delta
            idx += idx & -idx

    def query(self, idx):
        res = 0
        while idx > 0:
            res += self.tree[idx]
            idx -= idx & -idx
        return res

    def range_query(self, l, r):
        if l > r:
            return 0
        return self.query(r) - self.query(l - 1)

